<?php
declare(strict_types=1);
namespace app\controller;
use think\Request; use think\facade\Cache; use think\facade\Db;
final class AgentResults { public function index(Request $r): \think\response\Json { $t=trim(str_ireplace('Bearer ','',(string)$r->header('authorization')));$s=$t!==''?Cache::get('token:'.$t):null;if(!is_array($s)||($s['scope']??'')!=='agent')return json(['code'=>401,'message'=>'未登录或登录已过期','data'=>null]);$name=trim((string)$r->param('lottery',''));$lid=(int)Db::name('lotteries')->alias('l')->join('site_lotteries sl','sl.lottery_id=l.id')->where('sl.site_id',(int)$s['site_id'])->where('l.name',$name)->value('l.id');if($lid<1)return json(['code'=>0,'message'=>'ok','data'=>['list'=>[]]]);$limit=(int)Db::name('settings')->where('site_id',(int)$s['site_id'])->where('key','draw_history_limit')->value('value');$limit=$limit>0?min(200,$limit):80;$size=min($limit,max(1,(int)$r->param('page_size',$limit)));$rows=Db::name('lottery_histories')->where('lottery_id',$lid)->order('open_time desc')->order('id desc')->limit($size)->select()->toArray();$list=[];foreach($rows as $h){$opened=(int)($h['is_opened']??1)===1;$nums=$opened?array_values(array_filter([(string)($h['one']??''),(string)($h['two']??''),(string)($h['three']??'')],fn($v)=>$v!=='')):[];$complete=count($nums)===3;$sum=$complete?array_sum(array_map('intval',$nums)):null;$list[]=['lottery'=>$name,'issue_no'=>(string)$h['code'],'draw_time'=>$h['open_time'],'numbers'=>$opened&&$complete?implode(',',$nums):'','sum_value'=>$opened?$sum:null,'size'=>$opened&&$complete?($sum>=14?'大':'小'):null,'parity'=>$opened&&$complete?($sum%2?'单':'双'):null,'span_value'=>$opened&&$complete?max(array_map('intval',$nums))-min(array_map('intval',$nums)):null,'pending'=>$opened?0:1];}return json(['code'=>0,'message'=>'ok','data'=>['list'=>$list]]); } }
